<script>
import axios from "axios";
import { mapGetters } from "vuex";
import LuckyWheel from "@/components/Spin.vue";

export default {
  name: "BonusPage",
  components: { LuckyWheel },
  data() {
    return {
      bonuses: [],
      jackpotValue: 500,
      jackpotLimit: 100000,
      showTooltip: false,
      showJackpotTooltip: false,
      showSubscribeTooltip: false,
      selectedBonus: null,
      timer: null,
      animating: false,
      showSpinModal: false,
    };
  },
  computed: {
    ...mapGetters(["authUser"]),
    jackpotAmount() {
      return `$${this.jackpotValue.toLocaleString("en-US", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      })}`;
    },

    // ✅ Kullanıcının aktif wallet'ı
    activeWallet() {
      const user = this.authUser.user;
      if (!user || !user.currency) return null;

      const { coinType, type, chain } = user.currency;
      return (
        user.wallets.find(
          (w) =>
            w.coinType === coinType && w.type === type && w.chain === chain
        ) || { balance: 0, coinType }
      );
    },

    // ✅ Vault'da o coin için locked amount
    activeVaultBalance() {
      const user = this.authUser.user;
      if (!user?.vault?.balances || !Array.isArray(user.vault.balances))
        return 0;

      const { coinType, type, chain } = user.currency || {};
      const vaultEntry = user.vault.balances.find(
        (v) => v.coinType === coinType && v.type === type && v.chain === chain
      );
      return vaultEntry ? vaultEntry.amount : 0;
    },
  },
  created() {
    this.fetchBonuses();
    const savedJackpot = localStorage.getItem("jackpotValue");
    if (savedJackpot) {
      this.jackpotValue = parseFloat(savedJackpot);
    }
  },
  mounted() {
    this.startJackpotCycle();
  },
  beforeUnmount() {
    if (this.timer) clearInterval(this.timer);
  },
  methods: {
    async fetchBonuses() {
      try {
        const res = await axios.get("/bonus-settings");
        this.bonuses = res.data.bonuses.map((b) => ({
          type: b.type,
          title: `bonus.${b.type}`,
          percent: b.percentage,
          enabled: b.enabled,
          image: this.getImageByType(b.type),
          description: this.getDescriptionByType(b.type),
        }));
      } catch (err) {
        console.error("Bonus fetch error:", err);
      }
    },
    startJackpotCycle() {
      this.timer = setInterval(() => {
        if (!this.animating) {
          const increase = this.getDeterministicRandom(200, 600);
          this.animateJackpot(increase);
        }
      }, this.getDeterministicRandom(3000, 7000));
    },
    animateJackpot(increase) {
      this.animating = true;
      const start = this.jackpotValue;
      let target = start + increase;
      if (target >= this.jackpotLimit) {
        target = 0;
      }
      const duration = 1000;
      const startTime = performance.now();
      const step = (now) => {
        const progress = Math.min((now - startTime) / duration, 1);
        this.jackpotValue = start + (target - start) * progress;
        if (progress < 1) {
          requestAnimationFrame(step);
        } else {
          this.jackpotValue = target;
          localStorage.setItem("jackpotValue", this.jackpotValue.toString());
          this.animating = false;
        }
      };
      requestAnimationFrame(step);
    },
    getDeterministicRandom(min, max) {
      const seed = Math.floor(Date.now() / 10000);
      const x = Math.sin(seed) * 10000;
      const rnd = x - Math.floor(x);
      return Math.floor(rnd * (max - min + 1)) + min;
    },
    openModal(bonus) {
      this.selectedBonus = bonus;
    },
    closeModal() {
      this.selectedBonus = null;
    },
    getImageByType(type) {
      switch (type) {
        case "first_deposit":
        case "second_deposit":
        case "third_deposit":
        case "fourth_deposit":
        case "regular_deposit":
          return "@/assets/img/rewards/bonus.png";
        default:
          return "@/assets/img/rewards/bonus.png";
      }
    },
    getDescriptionByType(type) {
      switch (type) {
        case "first_deposit":
          return "Get a huge reward on your very first deposit!";
        case "second_deposit":
          return "Boost your balance with a generous second deposit bonus.";
        case "third_deposit":
          return "Enjoy more playtime with our third deposit offer.";
        case "fourth_deposit":
          return "Keep winning with a fourth deposit reward.";
        case "regular_deposit":
          return "Daily deposit bonus for consistent players.";
        default:
          return "Special bonus just for you!";
      }
    },
     openSpinModal() {
      this.showSpinModal = true;
    },
    closeSpinModal() {
      this.showSpinModal = false;
    },
  },
};
</script>





