<template>
  <div class="wheel-wrapper">
    <canvas ref="canvasRef" width="400" height="400" class="wheel-canvas"></canvas>
    <div class="pointer"></div>
    <div class="banner-text">Lucky Wheel</div>

    <button class="spin-btn" @click="startSpin" :disabled="spinning">
      {{ spinning ? "Spinning..." : "SPIN" }}
    </button>

    <!-- 🟣 Kazanılan ödül modalı -->
    <div v-if="showModal" class="result-modal" @click.self="closeModal">
      <div class="modal-content">
        <h2>🎉 Tebrikler!</h2>
        <p>Kazandığın ödül:</p>
        <div class="reward">{{ wonPrize.label }}</div>
        <button class="close-btn" @click="closeModal">Kapat</button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from "vue";

const canvasRef = ref(null);
const ctx = ref(null);
const SEGMENTS = 8;

const spinning = ref(false);
const rotation = ref(0);
const currentRotation = ref(0);
const showModal = ref(false);
const wonPrize = ref({ label: "" });

const prizes = [
  { label: "25,000", color: "#FF4081" },
  { label: "❤️", color: "#9C27B0" },
  { label: "2,000", color: "#3F51B5" },
  { label: "👑 Royalty", color: "#4CAF50" },
  { label: "5,000", color: "#FF9800" },
  { label: "x2 Credits", color: "#00BCD4" },
  { label: "💰 Bonus", color: "#E91E63" },
  { label: "x3 Credits", color: "#8BC34A" },
];

const drawWheel = () => {
  const canvas = canvasRef.value;
  const c = (ctx.value = canvas.getContext("2d"));
  const radius = canvas.width / 2;
  const segAngle = (2 * Math.PI) / SEGMENTS;

  c.clearRect(0, 0, canvas.width, canvas.height);
  c.save();
  c.translate(radius, radius);
  c.rotate((rotation.value * Math.PI) / 180);

  // Dış parlak halka
  const outerGrad = c.createRadialGradient(0, 0, radius * 0.7, 0, 0, radius);
  outerGrad.addColorStop(0, "#fff2");
  outerGrad.addColorStop(1, "#000");
  c.beginPath();
  c.arc(0, 0, radius, 0, 2 * Math.PI);
  c.fillStyle = outerGrad;
  c.fill();

  // Dilimleri çiz
  for (let i = 0; i < SEGMENTS; i++) {
    const start = i * segAngle;
    const end = start + segAngle;

    const grad = c.createLinearGradient(-radius, 0, radius, 0);
    grad.addColorStop(0, "#111");
    grad.addColorStop(0.3, prizes[i].color);
    grad.addColorStop(1, "#000");

    c.beginPath();
    c.moveTo(0, 0);
    c.arc(0, 0, radius - 8, start, end);
    c.closePath();
    c.fillStyle = grad;
    c.fill();

    // Dilim kenar çizgisi
    c.strokeStyle = "#fff3";
    c.lineWidth = 2;
    c.stroke();

    // Yazılar
    c.save();
    c.fillStyle = "#fff";
    c.font = "bold 16px 'Poppins'";
    c.textAlign = "center";
    c.textBaseline = "middle";
    c.rotate(start + segAngle / 2);
    c.translate(radius * 0.6, 0);
    c.rotate(Math.PI / 2);
    c.fillText(prizes[i].label, 0, 0);
    c.restore();
  }

  // Orta merkez 3D görünüm
  const centerGrad = c.createRadialGradient(0, 0, 5, 0, 0, 60);
  centerGrad.addColorStop(0, "#fff");
  centerGrad.addColorStop(1, "#ffca28");

  c.beginPath();
  c.arc(0, 0, 60, 0, 2 * Math.PI);
  c.fillStyle = centerGrad;
  c.shadowColor = "#0006";
  c.shadowBlur = 8;
  c.fill();

  c.restore();
};

// Easing fonksiyonu
const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);

const animateSpin = (target, duration = 6000) => {
  const start = performance.now();
  const initial = rotation.value;

  const step = (now) => {
    const elapsed = now - start;
    const progress = Math.min(elapsed / duration, 1);
    const eased = easeOutCubic(progress);

    rotation.value = initial + (target - initial) * eased;
    drawWheel();

    if (progress < 1) {
      requestAnimationFrame(step);
    } else {
      spinning.value = false;

      // Kazanan dilimi hesapla
      const normalized = (rotation.value % 360 + 360) % 360;
      const segAngle = 360 / SEGMENTS;
      const winner =
        Math.floor((360 - normalized + segAngle / 2) / segAngle) % SEGMENTS;

      wonPrize.value = prizes[winner];
      showModal.value = true;
    }
  };
  requestAnimationFrame(step);
};

const startSpin = () => {
  if (spinning.value) return;
  spinning.value = true;

  const randomIndex = Math.floor(Math.random() * SEGMENTS);
  const segAngle = 360 / SEGMENTS;
  const extraSpins = 5 * 360;
  const final =
    extraSpins + (360 - randomIndex * segAngle) - segAngle / 2;

  animateSpin(currentRotation.value + final);
  currentRotation.value += final;
};

const closeModal = () => {
  showModal.value = false;
};

onMounted(() => {
  drawWheel();
});
</script>

<style scoped>
.wheel-wrapper {
  position: relative;
  width: 100%;
  max-width: 340px;
  margin: 50px auto;
  text-align: center;
}

.wheel-canvas {
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #222, #000);
  box-shadow: inset 0 0 30px #000, 0 0 25px rgba(255, 255, 255, 0.15);
}

/* Pointer */
.pointer {
  position: absolute;
  top: -5px;
  left: 50%;
  width: 0;
  height: 0;
  border-left: 18px solid transparent;
  border-right: 18px solid transparent;
  border-bottom: 35px solid #ffdf5c;
  transform: translateX(-50%);
  filter: drop-shadow(0 0 10px #fff);
  z-index: 10;
}

/* Banner text */
.banner-text {
  position: absolute;
  bottom: 30px;
  left: 50%;
  transform: translateX(-50%);
  color: #fff;
  font-size: 22px;
  font-weight: 900;
  text-shadow: 0 0 8px #000, 0 0 10px #ff80ff;
  font-family: "Poppins", sans-serif;
}

/* Spin button */
.spin-btn {
  position: absolute;
  bottom: -70px;
  left: 50%;
  transform: translateX(-50%);
  background: linear-gradient(180deg, #ffca28, #f57c00);
  color: #fff;
  border: none;
  border-radius: 12px;
  padding: 12px 40px;
  font-size: 18px;
  font-weight: bold;
  cursor: pointer;
  box-shadow: 0 4px #8d6e63;
  transition: transform 0.15s;
}
.spin-btn:hover {
  transform: translateX(-50%) scale(1.05);
}
.spin-btn:active {
  transform: translateX(-50%) translateY(2px);
}

/* Modal */
.result-modal {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.75);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 50;
  animation: fadeIn 0.3s;
}
.modal-content {
  background: #111;
  border-radius: 14px;
  padding: 30px 40px;
  text-align: center;
  color: #fff;
  box-shadow: 0 0 20px #000;
  animation: scaleIn 0.4s ease;
}
.reward {
  margin: 15px 0;
  font-size: 28px;
  font-weight: 700;
  color: #ffca28;
}
.close-btn {
  background: #ff9800;
  border: none;
  padding: 10px 20px;
  border-radius: 8px;
  color: #fff;
  cursor: pointer;
  font-weight: bold;
}
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes scaleIn {
  from { transform: scale(0.8); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}
</style>
