import AvatarImage from '@/components/AvatarImage';
import { getCurrencySymbol } from '@/utils';
export default {
  data() {
    return {
      user: {
        avatar: require('@/assets/img/ranks/admin.svg'), // Örnek avatar URL'i
        user_id: '',
        username: '',
        rakeback: 5,
        vip_image: 'https://static.vecteezy.com/system/resources/previews/035/234/043/non_2x/3d-icon-verify-account-png.png', // Örnek VIP resmi URL'i
        vip_level: 'Gold'
      },
      
      totalSpins: '', // Toplam Çevrim
      totalDeposit: '', // Toplam Para Yatırma
      totalWithdrawal: '', // Toplam Para Çekme
      topButtons: [
        {
          id: 1,
          image: 'https://via.placeholder.com/50', // Buton 1 resmi
          text: this.$t('profile.bonushistory'),
          route: '/bonushistory'
        },
        {
          id: 2,
          image: 'https://via.placeholder.com/50', // Buton 2 resmi
          text: this.$t('profile.gamehistory'),
          route: '/gamehistory'
        },
        {
          id: 3,
          image: 'https://via.placeholder.com/50', // Buton 3 resmi
          text: this.$t('profile.Transaction History'),
          route: '/transactions'
        },
        {
          id: 4,
          image: 'https://via.placeholder.com/50', // Buton 4 resmi
          text: this.$t('profile.Account Information'),
          route: '/userprofile'
        }
      ],
      bottomButtons: [
      {
          id: 8,
          image: require('@/assets/img/profile/notifications.svg'), // Buton 8 resmi
          text: this.$t('profile.Notifications'),
          route: '/news'
        },
        {
          id: 5,
          image: require('@/assets/img/profile/team.svg'), // Buton 5 resmi
          text: this.$t('profile.MyTeam'),
          route: '/affiliates'
        },
        {
          id: 6,
          image: require('@/assets/img/profile/promo.svg'), // Buton 6 resmi
          text: this.$t('profile.promo'),
          route: '/promotions'
        },
        {
          id: 7,
          image: require('@/assets/img/profile/bonus.svg'), // Buton 7 resmi
          text: this.$t('profile.Rewards'),
          route: '/rewards'
        },
        
        {
          id: 9,
          image: require('@/assets/img/profile/support.svg'), // Buton 9 resmi
          text: this.$t('profile.Customer Services'),
          route: '/helper'
        },
        {
          id: 10,
          image: require('@/assets/img/profile/download.svg'), // Buton 10 resmi
          text: this.$t('profile.Download APP'),
          route: '/profile'
        } 
       
        
      ]
    };
  },
 
        components: {
            AvatarImage
        },
        computed: {

          
  ...mapGetters(['authUser', 'authActiveWalletBalance','vipLevel']),
  ...mapGetters('vip', [
  'userVip',
  'userXp',
  'vipLevel',
  'nextVipLevel',
  'vipNextXp',
  'vipProgress',
  'vipDisplayXp'
]),

 formattedBalance() {
    if (!this.authActiveWalletBalance || isNaN(this.authActiveWalletBalance)) return '0.00';
    return Number(this.authActiveWalletBalance).toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
  },

  // XP formatlı (2 hane)
  formattedVipXp() {
    if (!this.vipDisplayXp || isNaN(this.vipDisplayXp)) return '0.00';
    return Number(this.vipDisplayXp).toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
  },
  formattedNextXp() {
    if (!this.vipNextXp || isNaN(this.vipNextXp)) return '0.00';
    return Number(this.vipNextXp).toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
  },

  selectedFiat() {
    return this.authUser?.user?.currency?.fiatCurrency || 'USD';
  },
    
    
vipBadgeImage() {
  const base = process.env.VUE_APP_BACKEND_URL;
  const img = this.vipLevel?.vipBadgeImage;
  return img ? `${base}${img.startsWith('/') ? '' : '/'}${img}` : null;
},

 statsItems() {
    const stats = this.authUser.user.stats || {};
    return [
      {
        icon: require('@/assets/icons/bet.png'),
        label: this.$t('profile.Wager'),
        value: stats.bet || 0
      },
      {
        icon: require('@/assets/icons/won.png'),
        label: this.$t('profile.Win'),
        value: stats.won || 0
      },
      {
        icon: require('@/assets/icons/deposit.png'),
        label: this.$t('profile.Deposit'),
        value: stats.deposit || 0
      },
      {
        icon: require('@/assets/icons/withdrawal.png'),
        label: this.$t('profile.Withdrawal'),
        value: stats.withdraw || 0
      }
    ];
  }


},
  methods: {
   
    ...mapActions([
                'notificationShow'
            ]),
             getCurrencySymbol,
 
    copyUserId() {
      const input = this.$refs.userIdInput;
      input.select();
      document.execCommand('copy');
      alert(this.$t('profile.copy') + input.value);
    },
    navigateTo(route) {
      this.$router.push(route); // Vue Router ile yönlendirme
    }
  }
};
