<template>
  <div class="stats-wrapper">
    <div class="stats-box">
      <div class="stat-item">
        <div class="label">{{ $t('affiliate.commissionRate') }}</div>
        <div class="value">
          {{ selectedTab === 'Level 1' ? '%7' : selectedTab === 'Level 2' ? '%3' : '%1' }}
        </div>
      </div>
      <div class="divider"></div>

      <div class="stat-item">
        <div class="label">{{ $t('affiliate.totalReferrals') }}</div>
        <div class="value">{{ selectedReferredList.length }}</div>
      </div>
      <div class="divider"></div>

      <div class="stat-item">
        <div class="label">{{ $t('affiliate.totalWagered') }}</div>
        <div class="value">${{ totalWagered }}</div>
      </div>
      <div class="divider"></div>

      <div class="stat-item">
        <div class="label">{{ $t('affiliate.totalEarned') }}</div>
        <div class="value">${{ totalEarnedByLevel }}</div>
      </div>
    </div>

    <div class="claim-box">
      <div class="claim-text">
        <div class="label">{{ $t('affiliate.availableCommission') }}</div>
        <div class="value">
          ${{ affiliatesData.data ? formatValue(affiliatesData.data.available) : '0.00' }}
        </div>
      </div>
      <button @click="claimCommission" class="claim-btn">{{ $t('affiliate.claim') }}</button>
    </div>
  </div>
</template>



<script>
import { mapGetters, mapActions } from 'vuex';

export default {
  name: 'AffiliateStats',
  props: {
    selectedTab: {
      type: String,
      required: true
    }
  },
  computed: {
    ...mapGetters(['affiliatesData', 'socketSendLoading']),
    selectedReferredList() {
      switch (this.selectedTab) {
        case 'Level 1': return this.affiliatesData.referred || [];
        case 'Level 2': return this.affiliatesData.referredLevel2 || [];
        case 'Level 3': return this.affiliatesData.referredLevel3 || [];
        default: return [];
      }
    },
    totalWagered() {
      const total = this.selectedReferredList.reduce((sum, ref) => sum + (ref?.user?.stats?.bet || 0), 0);
      return this.formatValue(total);
    },
    totalEarnedByLevel() {
      const total = this.selectedReferredList.reduce((sum, ref) => sum + (ref?.affiliates?.generated || 0), 0);
      return this.formatValue(total);
    }
  },
  methods: {
    ...mapActions(['notificationShow', 'affiliatesSendClaimEarningsSocket']),
    claimCommission() {
      if (this.socketSendLoading !== null) return;
      if (this.affiliatesData.data?.available < 100) {
        this.notificationShow({ type: 'error', message: 'You’ll need a minimum of 100 Robux in earnings to claim.' });
        return;
      }
      this.affiliatesSendClaimEarningsSocket({});
    },
    formatValue(value) {
      return value.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    }
  }
};
</script>


