<template>
  <div class="referral-list-container">
    <div class="referral-table">
      <div class="table-header">
        <div class="header-cell">{{ $t('affiliate.nickname') }}</div>
        <div class="header-cell">{{ $t('affiliate.dateOfRegister') }}</div>
        <div class="header-cell">{{ $t('affiliate.totalDeposit') }}</div>
        <div class="header-cell">{{ $t('affiliate.totalWithdrawal') }}</div>
        <div class="header-cell">{{ $t('affiliate.totalWager') }}</div>
        <div class="header-cell">{{ $t('affiliate.commissionEarned') }}</div>
      </div>
      
      <div class="table-body">
        <div 
          v-for="(ref, index) in selectedReferredList" 
          :key="index" 
          class="table-row"
        >
          <div class="table-cell user-cell" :data-label="$t('affiliate.nickname')">
            <img :src="ref.user?.avatar" alt="avatar" class="avatar-img" />
            <span>{{ ref.user?.username || $t('affiliate.anonymous') }}</span>
          </div>
          <div class="table-cell" :data-label="$t('affiliate.dateOfRegister')">
            {{ formatDate(ref.user?.createdAt) }}
          </div>
          <div class="table-cell" :data-label="$t('affiliate.totalDeposit')">
            ${{ Number(ref.user?.stats?.deposit || 0).toFixed(2) }}
          </div>
          <div class="table-cell" :data-label="$t('affiliate.totalWithdrawal')">
            ${{ Number(ref.user?.stats?.withdraw || 0).toFixed(2) }}
          </div>
          <div class="table-cell" :data-label="$t('affiliate.totalWager')">
            ${{ Number(ref.user?.stats?.bet || 0).toFixed(2) }}
          </div>
          <div class="table-cell" :data-label="$t('affiliate.commissionEarned')">
            ${{ (ref.affiliates?.generated || 0).toFixed(2) }}
          </div>
        </div>
      </div>
    </div>
    
    <div class="load-more-container">
      <button class="load-more-btn">{{ $t('affiliate.loadMore') }}</button>
    </div>
  </div>
</template>


<script>
import { mapGetters } from 'vuex';

export default {
  name: 'AffiliateReferralList',
  props: {
    selectedTab: {
      type: String,
      required: true
    }
  },
  computed: {
    ...mapGetters(['affiliatesData']),
    selectedReferredList() {
      switch (this.selectedTab) {
        case 'Level 1': return this.affiliatesData.referred || [];
        case 'Level 2': return this.affiliatesData.referredLevel2 || [];
        case 'Level 3': return this.affiliatesData.referredLevel3 || [];
        default: return [];
      }
    }
  },
  methods: {
    formatDate(date) {
      if (!date) return '-';
      const d = new Date(date);
      return d.toLocaleDateString('en-GB', {
        day: '2-digit',
        month: 'long',
        year: 'numeric'
      });
    }
  }
};
</script>

<style scoped>
.referral-list-container {
  position: relative;
  border-radius: 8px;
  background: var(--background);
 
  overflow: hidden;
  z-index: 1;
  margin-top: 10px;
}

 


.referral-table {
  width: 100%;
  display: flex;
  flex-direction: column;
}



.table-header {
  display: flex;
  background: rgba(0, 0, 0, 0.2);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.header-cell {
  flex: 1;
  padding: 16px 12px;
  text-align: left;
  font-size: 0.875rem;
  font-weight: 600;
  color: #7b6cb9;
}

.table-body {
  display: flex;
  flex-direction: column;
}

.table-row {
  display: flex;
  border-bottom: 1px solid #334155;
  transition: background 0.2s;
}

 

.table-cell {
  flex: 1;
  padding: 12px;
  font-size: 0.875rem;
  color: #fff;
  font-weight: bold;
  display: flex;
  align-items: center;
}

.user-cell {
  gap: 8px;
}

.avatar-img {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  object-fit: cover;
}

.load-more-container {
  padding: 16px;
  text-align: center;
  border-top: 1px solid #334155;
  
}

.load-more-btn {
    background: var(--buttonyellow);
    box-shadow: var(--buttonyellowbox);
    color: #fff;
        text-shadow: -1px -1px 0 var(--roo-btn-text-stroke-color, #C56A18), 1px -1px 0 var(--roo-btn-text-stroke-color, #C56A18), -1px 1px 0 var(--roo-btn-text-stroke-color, #C56A18), 1px 1px 0 var(--roo-btn-text-stroke-color, #C56A18);
  border-radius: 12px;
   
  padding: 10px 24px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  min-width: 150px;
    
   
}

 

/* 🔽 Mobile optimizations */
@media (max-width: 768px) {
  .table-header {
    display: none;
  }

  .table-row {
    flex-direction: column;
    padding: 12px;
    border-bottom: 1px solid #2a3344;
  }

  .table-cell {
    display: flex;
    justify-content: space-between;
    padding: 6px 0;
    font-size: 0.85rem;
  }

  .table-cell::before {
    content: attr(data-label);
    font-weight: 600;
    color: #94a3b8;
    margin-right: 12px;
  }

  .user-cell {
    flex-direction: row;
    align-items: center;
  }

  .avatar-img {
    width: 35px;
    height: 35px;
  }

  .load-more-container {
  padding: 16px;
  text-align: center;
  border-top: 1px solid #334155;
  background: rgba(0, 0, 0, 0.2);
}
}

</style>