<template>
  <div class="referral-tabs-wrapper">
    <div class="referral-tabs">
      <button 
        v-for="tab in tabs"
        :key="tab"
        :class="['tab-button', { active: modelValue === tab }]"
        @click="selectTab(tab)"
      >
        {{ $t(`affiliate.tabs.${tab}`) }}
      </button>
    </div>

    <!-- Claim box (visible on mobile) -->
    <div class="claim-box-mobile" v-if="isMobile && affiliatesData && affiliatesData.data">
      <div class="claim-content">
        <div class="claim-text">
          <div class="label">{{ $t('affiliate.availableCommission') }}</div>
          <div class="value">
            ${{ formatValue(affiliatesData.data.available) }}
          </div>
        </div>
        <button @click="claimCommission" class="claim-btn">{{ $t('affiliate.claim') }}</button>
      </div>
    </div>
  </div>
</template>

<script>
import { mapGetters, mapActions } from 'vuex';

export default {
  name: 'AffiliateTabs',
  props: {
    modelValue: {
      type: String,
      required: true
    }
  },
  data() {
    return {
      tabs: ['Level 1', 'Level 2', 'Level 3'],
      isMobile: false
    };
  },
  computed: {
    ...mapGetters(['affiliatesData', 'socketSendLoading'])
  },
  methods: {
    ...mapActions(['notificationShow', 'affiliatesSendClaimEarningsSocket']),
    checkIfMobile() {
      this.isMobile = window.innerWidth <= 768;
    },
    selectTab(tab) {
      this.$emit('update:modelValue', tab);
    },
    claimCommission() {
      if (this.socketSendLoading !== null) return;
      if (this.affiliatesData.data?.available < 100) {
        this.notificationShow({
          type: 'error',
          message: "You'll need a minimum of 100 in earnings to claim."
        });
        return;
      }
      this.affiliatesSendClaimEarningsSocket({});
    },
    formatValue(value) {
      return value
        .toFixed(2)
        .replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    }
  },
  mounted() {
    this.checkIfMobile();
    window.addEventListener('resize', this.checkIfMobile);
  },
  beforeUnmount() {
    window.removeEventListener('resize', this.checkIfMobile);
  }
};
</script>

<style scoped>
.referral-tabs-wrapper {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 10px;
  margin-bottom: 10px;
}

.referral-tabs {
  display: flex;
  gap: 6px;
  background: var(--background);
  border-radius: 12px;
  padding: 15px;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.05);
  position: relative;
  z-index: 1;
  align-items: center;
  justify-content: space-between;
}



.tab-button {
  padding: 8px 14px;
  border: none;
  border-radius: 8px;
  background: var(--background2);
  color: #fff;
  font-weight: 600;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
  flex: 1;
  text-align: center;
}

.tab-button.active {
      background: var(--buttonyellow);
    box-shadow: var(--buttonyellowbox);
    color: #fff;
        text-shadow: -1px -1px 0 var(--roo-btn-text-stroke-color, #C56A18), 1px -1px 0 var(--roo-btn-text-stroke-color, #C56A18), -1px 1px 0 var(--roo-btn-text-stroke-color, #C56A18), 1px 1px 0 var(--roo-btn-text-stroke-color, #C56A18);
}

/* PC'de görünmeyecek */
.claim-box-mobile {
  display: none;
}

/* Mobil stil ayarları */
@media (max-width: 768px) {
  .referral-tabs-wrapper {
    flex-direction: row;
    align-items: center;
    gap: 8px;
  }

  .referral-tabs {
    flex: 1;
    padding: 10px;
  }

  .tab-button {
    padding: 6px 8px;
    font-size: 12px;
  }

  /* Mobilde görünecek claim kutusu */
  .claim-box-mobile {
    display: flex !important;
    background: var(--background);
    border-radius: 12px;
    padding: 1px;
    position: relative;
    min-width: 150px;
    height: 50px;
    z-index: 1;
  }

 
 
 



  .claim-content {
    display: flex;
    align-items: center;
    padding: 0 10px;
    width: 100%;
    height: 100%;
    
    border-radius: 12px;
  }

  .claim-text {
    flex: 1;
  }

  .claim-text .label {
    font-size: 10px;
    color: #94a3b8;
    line-height: 1.2;
  }

  .claim-text .value {
    font-size: 13px;
    font-weight: 600;
    color: #ffffff;
    line-height: 1.3;
  }

  .claim-btn {
       box-shadow: rgb(35, 32, 66) 0px -3px 0px 0px inset, rgb(89, 81, 142) 0px 2px 0px 0px inset;
    text-shadow: rgb(25, 25, 57) 0px 1px 0px;
    border: 4px solid var(--roo-btn-outline-color, #090C1D);
    background: rgb(44, 40, 82);
    border-radius: 12px;
    color: white;
    padding: 5px 8px;
    font-weight: 600;
    font-size: 12px;
    cursor: pointer;
    margin-left: 8px;
    white-space: nowrap;
  }

  .claim-btn:hover {
    opacity: 0.9;
  }
}
</style>