<template>
  <div class="user-info">
    <!-- Top Area -->
    <div class="top-bar">
      <div class="left">
        <div class="avatar-wrapper">
          <AvatarImage :image="authUser.user.avatar" />
        </div>
        <div class="username-area">
          <div class="username">@{{ authUser.user.username }}</div>
          <!-- 🔽 Yeni eklenen toplam istatistikler -->
          <div class="totals">
            <div class="top-row">
              <div class="total-item">
                <span class="label">{{ $t('affiliate.totalReferrals') }}:</span>
                <span class="value">{{ totalReferrals }}</span>
              </div>
              <div class="total-item">
                <span class="label">{{ $t('affiliate.totalEarned') }}:</span>
                <span class="value">${{ totalEarned.toFixed(2) }}</span>
              </div>
            </div>
            <div class="bottom-row">
              <div class="total-item">
                <span class="label">{{ $t('affiliate.totalWager') }}:</span>
                <span class="value">${{ totalWager.toFixed(2) }}</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- Code entry area -->
    <div v-if="!hasAffiliateCode" class="code-entry">
      <input
        v-model="affiliatesCode"
        type="text"
        :placeholder="$t('affiliate.setReferralCode')"
      />
      <button @click="submitCode" :disabled="socketSendLoading !== null">
        {{ $t('affiliate.setCode') }}
      </button>
    </div>

    <!-- Bottom Area -->
    <div v-else class="info-boxes">
      <div class="box referral-id-box">
        <div class="label">{{ $t('affiliate.yourReferralId') }}</div>
        <div class="value">{{ affiliatesData.data.code }}</div>
        <button class="copy-button" @click="copyCode"><IconCopy /></button>
      </div>
      <div class="box">
        <div class="label">{{ $t('affiliate.yourReferralLink') }}</div>
        <div class="value">https://velobet280.com/?a={{ affiliatesData.data.code }}</div>
        <button class="copy-button" @click="copyCode"><IconCopy /></button>
      </div>

      <!-- Social Share box -->
      <div class="box social-share">
        <div class="social-buttons">
          <a :href="`https://twitter.com/intent/tweet?text=Join%20me%20on%20Rivobit!%20https://velobet280.com/?a=${affiliatesData.data?.code}`" target="_blank" rel="noopener">
            <img src="@/assets/icons/twitter.png" alt="Twitter" />
          </a>
          <a :href="`https://www.facebook.com/sharer/sharer.php?u=https://velobet280.com/?a=${affiliatesData.data?.code}`" target="_blank" rel="noopener">
            <img src="@/assets/icons/facebook.png" alt="Facebook" />
          </a>
          <a :href="`https://wa.me/?text=Join%20me%20on%20Rivobit!%20https://velobet280.com/?a=${affiliatesData.data?.code}`" target="_blank" rel="noopener">
            <img src="@/assets/icons/whatsapp.png" alt="WhatsApp" />
          </a>
          <a :href="`https://t.me/share/url?url=https://velobet280.com/?a=${affiliatesData.data?.code}&text=Join%20me%20on%20Rivobit!`" target="_blank" rel="noopener">
            <img src="@/assets/icons/telegram.png" alt="Telegram" />
          </a>
          <a :href="`https://www.instagram.com/`" target="_blank" rel="noopener">
            <img src="@/assets/icons/instagram.png" alt="Instagram" />
          </a>
          <a :href="`https://www.tiktok.com/`" target="_blank" rel="noopener">
            <img src="@/assets/icons/tiktok.png" alt="TikTok" />
          </a>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { mapGetters, mapActions } from 'vuex';
import AvatarImage from '@/components/AvatarImage.vue';
import IconCopy from '@/components/icons/IconCopy.vue';

export default {
  name: 'AffiliateUserInfo',
  components: {
    AvatarImage,
    IconCopy
  },
  data() {
    return {
      selectedTab: 'year',
      affiliatesCode: ''
    };
  },
  computed: {
    ...mapGetters(['authUser', 'affiliatesData', 'socketSendLoading']),
    hasAffiliateCode() {
      return !!(this.affiliatesData.data?.code && this.affiliatesData.data.code.trim() !== '');
    },
    totalReferrals() {
      return (
        (this.affiliatesData.referred?.length || 0) +
        (this.affiliatesData.referredLevel2?.length || 0) +
        (this.affiliatesData.referredLevel3?.length || 0)
      );
    },
    totalWager() {
      const allRefs = [
        ...(this.affiliatesData.referred || []),
        ...(this.affiliatesData.referredLevel2 || []),
        ...(this.affiliatesData.referredLevel3 || [])
      ];
      return allRefs.reduce((sum, ref) => sum + (ref.user?.stats?.bet || 0), 0);
    },
    totalEarned() {
      const allRefs = [
        ...(this.affiliatesData.referred || []),
        ...(this.affiliatesData.referredLevel2 || []),
        ...(this.affiliatesData.referredLevel3 || [])
      ];
      return allRefs.reduce((sum, ref) => sum + (ref.affiliates?.generated || 0), 0);
    }
  },
  watch: {
    'affiliatesData.data': {
      handler(data) {
        if (data?.code) this.affiliatesCode = data.code;
      },
      immediate: true,
      deep: true
    }
  },
  methods: {
    ...mapActions(['notificationShow', 'affiliatesSendCodeSocket']),
    copyCode() {
      const code = this.affiliatesData.data?.code || this.affiliatesCode;
      if (!code) return;
      const el = document.createElement('textarea');
      el.value = `https://velobet280.com/?a=${code}`;
      el.setAttribute('readonly', '');
      el.style.position = 'absolute';
      el.style.left = '-9999px';
      document.body.appendChild(el);
      el.select();
      document.execCommand('copy');
      document.body.removeChild(el);
      this.notificationShow({ type: 'success', message: 'Copied to your clipboard.' });
    },
    submitCode() {
      if (!this.affiliatesCode || this.affiliatesCode.trim().length < 2) {
        this.notificationShow({ type: 'error', message: 'Your entered affiliate code is invalid.' });
        return;
      }
      this.affiliatesSendCodeSocket({ code: this.affiliatesCode });
      this.affiliatesCode = '';
    }
  }
};
</script>

